"""Independent explicit Cartesian tuples and first fiber-conflict semantics."""

ORIGINAL = 'fn original_descend(\n    source: &FinitePartialStructure,\n    quotient: &SortQuotient,\n) -> Result<FinitePartialStructure, DescentError> {\n    source.validate()?;\n    quotient.validate(source)?;\n    let mut operations = Vec::new();\n    for (operation_id, operation) in source.operations.iter().enumerate() {\n        let count = cardinality(&quotient.target_sizes, &operation.inputs)?;\n        let mut rows: Vec<Option<(usize, Option<usize>)>> = vec![None; count];\n        for (row, value) in operation.values.iter().enumerate() {\n            let image_row = quotient.tuple_image(&source.sizes, &operation.inputs, row);\n            let image = value.map(|value| quotient.maps[operation.output][value]);\n            if let Some((left, old)) = rows[image_row] {\n                if old != image {\n                    return Err(DescentError::OperationConflict {\n                        operation: operation_id,\n                        left,\n                        right: row,\n                        left_image: old,\n                        right_image: image,\n                    });\n                }\n            } else {\n                rows[image_row] = Some((row, image));\n            }\n        }\n        let values = rows\n            .into_iter()\n            .map(|row| {\n                row.map(|(_, value)| value)\n                    .ok_or(DescentError::InvalidSortMap)\n            })\n            .collect::<Result<_, _>>()?;\n        operations.push(PartialOperation {\n            inputs: operation.inputs.clone(),\n            output: operation.output,\n            values,\n        });\n    }\n    let mut predicates = Vec::new();\n    for (predicate_id, predicate) in source.predicates.iter().enumerate() {\n        let count = cardinality(&quotient.target_sizes, &predicate.inputs)?;\n        let mut rows: Vec<Option<(usize, bool)>> = vec![None; count];\n        for (row, &value) in predicate.values.iter().enumerate() {\n            let image_row = quotient.tuple_image(&source.sizes, &predicate.inputs, row);\n            if let Some((left, old)) = rows[image_row] {\n                if old != value {\n                    return Err(DescentError::PredicateConflict {\n                        predicate: predicate_id,\n                        left,\n                        right: row,\n                    });\n                }\n            } else {\n                rows[image_row] = Some((row, value));\n            }\n        }\n        let values = rows\n            .into_iter()\n            .map(|row| {\n                row.map(|(_, value)| value)\n                    .ok_or(DescentError::InvalidSortMap)\n            })\n            .collect::<Result<_, _>>()?;\n        predicates.push(Predicate {\n            inputs: predicate.inputs.clone(),\n            values,\n        });\n    }\n    Ok(FinitePartialStructure {\n        sizes: quotient.target_sizes.clone(),\n        operations,\n        predicates,\n    })\n}'

TESTS = r'''
fn tuples(sizes:&[usize],inputs:&[usize])->Vec<Vec<usize>>{let mut out=vec![Vec::new()];for &sort in inputs{let mut next=Vec::new();for row in out{for value in 0..sizes[sort]{let mut row=row.clone();row.push(value);next.push(row);}}out=next;}out}
fn image_tuple(tuple:&[usize],inputs:&[usize],q:&SortQuotient)->Vec<usize>{tuple.iter().zip(inputs).map(|(&x,&sort)|q.maps[sort][x]).collect()}
fn oracle(s:&FinitePartialStructure,q:&SortQuotient)->Result<FinitePartialStructure,DescentError>{let mut operations=Vec::new();let mut predicates=Vec::new();
 for (id,op) in s.operations.iter().enumerate(){let src=tuples(&s.sizes,&op.inputs);let target=tuples(&q.target_sizes,&op.inputs);let mut fibers:std::collections::BTreeMap<Vec<usize>,(usize,Option<usize>)>=Default::default();for (row,tuple) in src.iter().enumerate(){let key=image_tuple(tuple,&op.inputs,q);let value=op.values[row].map(|v|q.maps[op.output][v]);if let Some(&(left,old))=fibers.get(&key){if old!=value{return Err(DescentError::OperationConflict{operation:id,left,right:row,left_image:old,right_image:value});}}else{fibers.insert(key,(row,value));}}let values=target.iter().map(|key|fibers[key].1).collect();operations.push(PartialOperation{inputs:op.inputs.clone(),output:op.output,values});}
 for (id,p) in s.predicates.iter().enumerate(){let src=tuples(&s.sizes,&p.inputs);let target=tuples(&q.target_sizes,&p.inputs);let mut fibers:std::collections::BTreeMap<Vec<usize>,(usize,bool)>=Default::default();for (row,tuple) in src.iter().enumerate(){let key=image_tuple(tuple,&p.inputs,q);let value=p.values[row];if let Some(&(left,old))=fibers.get(&key){if old!=value{return Err(DescentError::PredicateConflict{predicate:id,left,right:row});}}else{fibers.insert(key,(row,value));}}let values=target.iter().map(|key|fibers[key].1).collect();predicates.push(Predicate{inputs:p.inputs.clone(),values});}
 Ok(FinitePartialStructure{sizes:q.target_sizes.clone(),operations,predicates})
}
fn compare(s:&FinitePartialStructure,q:&SortQuotient){let expected=oracle(s,q);let actual=descend(s,q);assert_eq!(actual,expected);assert_eq!(actual,original_descend(s,q));match actual{Ok(target)=>{assert_eq!(verify(s,q,&target),Ok(()));let mut bad=target;bad.sizes.push(7);assert_eq!(verify(s,q,&bad),Err(DescentError::ReceiptMismatch));},Err(error)=>{let unrelated=FinitePartialStructure{sizes:Vec::new(),operations:Vec::new(),predicates:Vec::new()};assert_eq!(verify(s,q,&unrelated),Err(error));}}}
#[test]fn exhaustive_binary_operations_predicates_and_sort_maps(){
 let maps=[SortQuotient{target_sizes:vec![1],maps:vec![vec![0,0]]},SortQuotient{target_sizes:vec![2],maps:vec![vec![0,1]]},SortQuotient{target_sizes:vec![2],maps:vec![vec![1,0]]}];let mut cases=0;
 for code in 0..81{let mut n=code;let values=(0..4).map(|_|{let v=n%3;n/=3;if v==0{None}else{Some(v-1)}}).collect::<Vec<_>>();for flags in 0usize..16{let s=FinitePartialStructure{sizes:vec![2],operations:vec![PartialOperation{inputs:vec![0,0],output:0,values:values.clone()}],predicates:vec![Predicate{inputs:vec![0,0],values:(0..4).map(|i|flags&(1<<i)!=0).collect()}]};for q in &maps{compare(&s,q);cases+=1;}}}assert_eq!(cases,3888);
}
#[test]fn multisort_tuple_order_nullary_and_first_conflict(){
 let q=SortQuotient{target_sizes:vec![2,2],maps:vec![vec![1,0],vec![1,0,1]]};
 for inputs in [vec![0,1],vec![1,0,1],vec![]]{let rows=tuples(&[2,3],&inputs);for code in 0usize..64{let values=rows.iter().enumerate().map(|(r,_)|match(code>>(r%6))%4{0=>None,n=>Some(n-1)}).collect();let s=FinitePartialStructure{sizes:vec![2,3],operations:vec![PartialOperation{inputs:inputs.clone(),output:1,values}],predicates:vec![Predicate{inputs:inputs.clone(),values:(0..rows.len()).map(|r|code&(1<<(r%6))!=0).collect()}]};compare(&s,&q);}}
 let empty=FinitePartialStructure{sizes:vec![],operations:vec![],predicates:vec![Predicate{inputs:vec![],values:vec![false]},Predicate{inputs:vec![],values:vec![true]}]};let q=SortQuotient{target_sizes:vec![],maps:vec![]};compare(&empty,&q);assert_eq!(descend(&empty,&q).unwrap(),empty);
 let s=FinitePartialStructure{sizes:vec![0,1],operations:vec![PartialOperation{inputs:vec![0],output:1,values:vec![]},PartialOperation{inputs:vec![],output:1,values:vec![None]}],predicates:vec![Predicate{inputs:vec![0],values:vec![]}]};let q=SortQuotient{target_sizes:vec![0,1],maps:vec![vec![],vec![0]]};compare(&s,&q);
 let s=FinitePartialStructure{sizes:vec![0],operations:vec![PartialOperation{inputs:vec![],output:0,values:vec![None]}],predicates:vec![]};let q=SortQuotient{target_sizes:vec![0],maps:vec![vec![]]};compare(&s,&q);assert_eq!(descend(&s,&q).unwrap().operations[0].values,vec![None]);
 let s=FinitePartialStructure{sizes:vec![3],operations:vec![PartialOperation{inputs:vec![0],output:0,values:vec![None,Some(1),Some(2)]},PartialOperation{inputs:vec![0],output:0,values:vec![None;3]}],predicates:vec![Predicate{inputs:vec![0],values:vec![true,false,true]}]};let q=SortQuotient{target_sizes:vec![1],maps:vec![vec![0,0,0]]};assert_eq!(descend(&s,&q),Err(DescentError::OperationConflict{operation:0,left:0,right:1,left_image:None,right_image:Some(0)}));let mut s=s;s.operations[0].values=vec![None;3];assert_eq!(descend(&s,&q),Err(DescentError::PredicateConflict{predicate:0,left:0,right:1}));
}
#[test]fn typed_admission_prefix_overflow_and_bad_receipts(){
 let blank=FinitePartialStructure{sizes:vec![2],operations:vec![],predicates:vec![]};
 for q in [SortQuotient{target_sizes:vec![],maps:vec![]},SortQuotient{target_sizes:vec![],maps:vec![vec![0,0]]},SortQuotient{target_sizes:vec![1],maps:vec![]},SortQuotient{target_sizes:vec![1],maps:vec![vec![0]]},SortQuotient{target_sizes:vec![2],maps:vec![vec![0,0]]},SortQuotient{target_sizes:vec![2],maps:vec![vec![2,0]]}]{assert_eq!(descend(&blank,&q),Err(DescentError::InvalidSortMap));}
 let q=SortQuotient{target_sizes:vec![1],maps:vec![vec![0,0]]};let bad=FinitePartialStructure{sizes:vec![2],operations:vec![PartialOperation{inputs:vec![99],output:99,values:vec![]}],predicates:vec![]};assert_eq!(descend(&bad,&q),Err(DescentError::InvalidSignature));let bad=FinitePartialStructure{sizes:vec![2],operations:vec![PartialOperation{inputs:vec![0],output:0,values:vec![Some(2),None]}],predicates:vec![]};assert_eq!(descend(&bad,&q),Err(DescentError::InvalidTable));let mut bad=bad;bad.operations[0].values.pop();assert_eq!(descend(&bad,&q),Err(DescentError::InvalidTable));
 let bad=FinitePartialStructure{sizes:vec![2],operations:vec![],predicates:vec![Predicate{inputs:vec![1],values:vec![]}]};assert_eq!(descend(&bad,&q),Err(DescentError::InvalidSignature));let mut bad=bad;bad.predicates[0].inputs=vec![0];assert_eq!(descend(&bad,&q),Err(DescentError::InvalidTable));
 assert_eq!(cardinality(&[],&[]),Ok(1));assert_eq!(cardinality(&[usize::MAX,2,0],&[0,1,2]),Err(DescentError::CardinalityOverflow));assert_eq!(cardinality(&[0,usize::MAX,2],&[0,1,2]),Ok(0));assert_eq!(cardinality(&[0],&[0,99]),Err(DescentError::InvalidSignature));
 let huge=FinitePartialStructure{sizes:vec![usize::MAX,2],operations:vec![PartialOperation{inputs:vec![0,1],output:0,values:vec![]}],predicates:vec![]};assert_eq!(descend(&huge,&q),Err(DescentError::CardinalityOverflow));
}
'''


def challenge(subject):
    return '\n#[cfg(test)]mod independent_partial_structure_tests{use super::*;\n'+ORIGINAL+TESTS+'\n}\n'
